import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const resStudents = await fetch("http://localhost:5000/api/student");
    const studentsData = await resStudents.json();
    setStudents(studentsData);

    const resSupervisors = await fetch("http://localhost:5000/api/admin");
    const supervisorsData = await resSupervisors.json();
    setSupervisors(supervisorsData);

    const resEvaluators = await fetch("http://localhost:5000/api/evaluator");
    const evaluatorsData = await resEvaluators.json();
    setEvaluators(evaluatorsData);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const userPayload = {
      username: name,
      email,
      password,
      role
    };

    if (editingIndex !== null) {
      // Not implemented PUT for update for brevity
      alert("Update logic not yet implemented.");
      return;
    }

    try {
      const userRes = await fetch("http://localhost:5000/api/user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(userPayload),
      });
      const user = await userRes.json();

      if (role === "Student") {
        await fetch("http://localhost:5000/api/student", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user._id,
            studentName: name,
            regNo: registrationNumber,
            isGrouped: false,
          }),
        });
      } else if (role === "Supervisor") {
        await fetch("http://localhost:5000/api/admin", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user._id,
            name,
          }),
        });
      } else if (role === "Evaluator") {
        await fetch("http://localhost:5000/api/evaluator", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user._id,
            name,
          }),
        });
      }

      await fetchUsers();
      resetForm();
      alert("User added successfully.");
    } catch (err) {
      console.error(err);
      alert("Error adding user.");
    }
  };

  const resetForm = () => {
    setName("");
    setEmail("");
    setRole("");
    setRegistrationNumber("");
    setPassword("");
    setEditingIndex(null);
    setEditingType("");
  };

  const handleDelete = async (userId, type) => {
    try {
      await fetch(`http://localhost:5000/api/user/${userId}`, {
        method: "DELETE",
      });

      const subRoute =
        type === "student"
          ? "student"
          : type === "supervisor"
          ? "admin"
          : "evaluator";

      await fetch(`http://localhost:5000/api/${subRoute}/user/${userId}`, {
        method: "DELETE",
      });

      await fetchUsers();
      alert("User deleted successfully.");
    } catch (err) {
      console.error(err);
      alert("Error deleting user.");
    }
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (!newPassword) return;

    try {
      await fetch(`http://localhost:5000/api/user/${userId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password: newPassword }),
      });
      alert("Password reset successfully.");
    } catch (err) {
      console.error(err);
      alert("Error resetting password.");
    }
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <form onSubmit={handleSubmit}>
            <label>Name:</label>
            <input value={name} onChange={(e) => setName(e.target.value)} required />

            <label>Email:</label>
            <input value={email} onChange={(e) => setEmail(e.target.value)} required />

            <label>Password:</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />

            <label>Role:</label>
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>

            {role === "Student" && (
              <>
                <label>Registration Number:</label>
                <input value={registrationNumber} onChange={(e) => setRegistrationNumber(e.target.value)} required />
              </>
            )}

            <button type="submit">{editingIndex !== null ? "Update" : "Submit"}</button>
          </form>

          <hr />

          <h2>Students</h2>
          <ul>
            {students.map((s, i) => (
              <li key={i}>
                {s.studentName} ({s.regNo})
                <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                <button onClick={() => handleDelete(s.userId, "student")}>Delete</button>
              </li>
            ))}
          </ul>

          <h2>Supervisors</h2>
          <ul>
            {supervisors.map((s, i) => (
              <li key={i}>
                {s.name}
                <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                <button onClick={() => handleDelete(s.userId, "supervisor")}>Delete</button>
              </li>
            ))}
          </ul>

          <h2>Evaluators</h2>
          <ul>
            {evaluators.map((s, i) => (
              <li key={i}>
                {s.name}
                <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                <button onClick={() => handleDelete(s.userId, "evaluator")}>Delete</button>
              </li>
            ))}
          </ul>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
